     7  static bool __check(RIO *io, const char *pathname, bool many) {
     8          const char *uris[] = {
     9                  "slurp://", "malloc://", "hex://", "stdin://", NULL
    10          };
    11          size_t i = 0;
    12          while (uris[i]) {
    13                  if (r_str_startswith (pathname, uris[i])) {
    14                          return true;
    15                  }
    16                  i++;
    17          }
    18          return false;
    19  }
