    21  static RIODesc *__open(RIO *io, const char *pathname, int rw, int mode) {
    22          if (__check (io, pathname, 0)) {
    23                  RIOMalloc *mal = R_NEW0 (RIOMalloc);
    24                  if (!mal) {
    25                          return NULL;
    26                  }
    27                  if (r_str_startswith (pathname, "slurp://")) {
    28                          size_t size;
    29                          char *buf = r_file_slurp (pathname + 8, &size);
    30                          if (!buf || size < 1) {
    31                                  free (mal);
    32                                  free (buf);
    33                                  return NULL;
    34                          }
    35                          mal->size = size;
    36                          mal->buf = (ut8*)buf;
    37                  } else if (r_str_startswith (pathname, "stdin://")) {
    38                          int size;
    39                          char *buf = r_stdin_slurp (&size);
    40                          if (!buf || size < 1) {
    41                                  free (mal);
    42                                  free (buf);
    43                                  return NULL;
    44                          }
    45                          mal->size = size;
    46                          mal->buf = (ut8*)buf;
    47                  } else if (r_str_startswith (pathname, "hex://")) {
    48                          mal->size = strlen (pathname);
    49                          mal->buf = calloc (1, mal->size + 1);
    50                          if (!mal->buf) {
    51                                  free (mal);
    52                                  return NULL;
    53                          }
    54                          mal->size = r_hex_str2bin (pathname + 6, mal->buf);
    55                          if ((int)mal->size < 1) {
    56                                  R_FREE (mal->buf);
    57                          }
    58                  } else {
    59                          mal->size = r_num_math (NULL, pathname + 9);
    60                          if (((int)mal->size) < 1) {
    61                                  free (mal);
    62                                  R_LOG_ERROR ("Cannot allocate (%s) 0 bytes", pathname + 9);
    63                                  return NULL;
    64                          }
    65                          mal->buf = calloc (1, mal->size + 1);
    66                  }
    67                  mal->offset = 0;
    68                  if (mal->buf) {
    69                          return r_io_desc_new (io, &r_io_plugin_malloc, pathname,
    70                                  R_PERM_RW | (rw & R_PERM_X), mode, mal);
    71                  }
    72                  R_LOG_ERROR ("Cannot allocate (%s) %d byte(s)", pathname + 9, mal->size);
    73                  free (mal);
    74          }
    75          return NULL;
    76  }
