    78  RIOPlugin r_io_plugin_malloc = {
    79          .meta = {
    80                  .name = "malloc",
    81                  .desc = "Memory allocation plugin",
    82                  .license = "LGPL3",
    83          },
    84          .uris = "malloc://,hex://,slurp://,stdin://",
    85          .open = __open,
    86          .close = io_memory_close,
    87          .read = io_memory_read,
    88          .check = __check,
    89          .seek = io_memory_lseek,
    90          .write = io_memory_write,
    91          .resize = io_memory_resize,
    92  };
